def _idle_expects(fault_kind):
    """The outcomes a persistent fault at idle can be judged against."""
    if fault_kind in BREAK_FAULTS:
        return IDLE_BREAK_EXPECTS
    if fault_kind == "node":
        return NODE_EXPECTS
    if fault_kind in LIFT_FAULTS:
        return LIFT_EXPECTS
    return set()
